import{z as t,x as s,o as r,c as n,q as E,j as o,D as e,d as l,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"lock-free 并行","description":"","frontmatter":{"title":"lock-free 并行","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-lockfree.md","filePath":"cs/par-lockfree.md","lastUpdated":1791413859000}'),c={name:"cs/par-lockfree.md"};function p(f,a,h,d,C,m){const A=s("Mermaid");return r(),n("div",null,[a[2]||(a[2]=E('<h1 id="lock-free-并行" tabindex="-1">lock-free 并行 <a class="header-anchor" href="#lock-free-并行" aria-label="Permalink to &quot;lock-free 并行&quot;">​</a></h1><div class="epigraph"><p>锁把进度押在持有者身上；无锁把进度写进对象的规格：无论谁被挂起，系统整体总在前进。</p><footer>—— 据 Herlihy and Shavit, The Art of Multiprocessor Programming；Herlihy, Wait-Free Synchronization, ACM TOCS 1991 整理</footer></div><p><a href="/cs/par-task-parallel">上一课</a>把不规则并行交给工作窃取，前提是任务之间几乎不共享可变状态。缺口就在共享数据结构本身：计数器、队列、哈希表被多核同时读写时怎么办。锁是一条路——<a href="/cs/spinlock">自旋锁</a>与 <a href="/cs/mcs-lock">MCS 锁</a>已给过排队与乒乓的账——但锁的病根是进度依赖持有者：持有者被抢占、被换出甚至崩溃，临界区外的所有人陪停。无锁结构把进度条件写进对象规格。本课写它的谱系、做法与代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进度条件是一条谱系：blocking（一个线程的意外能拦住全体）→ obstruction-free（无冲突时前进）→ lock-free（整体总有人在前进，个别线程可能饿）→ wait-free（每个线程都在有限步内前进）。每升一级，实现的复杂度与常数都显著上升。错法一：把「无锁」当「更快」——CAS 重试循环在争用下烧的是同一根缓存行的带宽，<a href="/cs/mcs-lock">MCS 锁</a>那种排队锁在高争用下反而更稳。错法二：手写 CAS 循环却省掉内存序——弱一致机器上重排会把「先检查后提交」的不变量打穿，<a href="/cs/acquire-release">acquire / release</a> 的语义正是为这一步存在的。</p><p><span class="marginnote">「无锁≠更快」可以类比买饭：CAS 循环像一窝蜂挤在窗口抢最后一份，抢不到的从头再来，人越多浪费越多；排队锁像取号叫号，看着笨，高峰期反而人人有确定进展。争用越凶，这两种的差距越明显。</span></p>',6)),(r(),o(i,null,{default:e(()=>[B(A,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22blocking%3A%20%E4%B8%80%E4%BA%BA%E8%A2%AB%E6%8C%82%E8%B5%B7%20%E5%85%A8%E4%BD%93%E9%99%AA%E5%81%9C%22%5D%20--%3E%20OF%5B%22obstruction-free%3A%20%E6%97%A0%E5%86%B2%E7%AA%81%E6%97%B6%E6%89%8D%E5%89%8D%E8%BF%9B%22%5D%0A%20%20OF%20--%3E%20LF%5B%22lock-free%3A%20%E7%B3%BB%E7%BB%9F%E6%95%B4%E4%BD%93%E6%80%BB%E5%9C%A8%E5%89%8D%E8%BF%9B%20%E4%B8%AA%E5%88%AB%E7%BA%BF%E7%A8%8B%E5%8F%AF%E8%83%BD%E9%A5%BF%22%5D%0A%20%20LF%20--%3E%20WF%5B%22wait-free%3A%20%E6%AF%8F%E4%B8%AA%E7%BA%BF%E7%A8%8B%E9%83%BD%E5%9C%A8%E6%9C%89%E9%99%90%E6%AD%A5%E5%86%85%E5%89%8D%E8%BF%9B%22%5D%0A%20%20WF%20--%3E%20UP%5B%22%E8%B6%8A%E5%BE%80%E5%8F%B3%20%E4%BF%9D%E8%AF%81%E8%B6%8A%E5%BC%BA%20%E5%AE%9E%E7%8E%B0%E8%B6%8A%E5%A4%8D%E6%9D%82%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主力是 CAS 循环：读当前值、算新值、CAS 提交，失败重读重试；<a href="/cs/atomic-rmw">原子读改写</a>给过 CAS/TAS/fetch_add 三类形态。实例用 Treiber 栈：入栈就是一次头指针 CAS，一行核心。两个必须正面处理的坑：ABA——CAS 只认值不认历史，指针绕一圈回来照样通过，对策是打标签、延迟回收或 <a href="/cs/hazard-pointer">无锁栈与 hazard pointer</a>；内存回收——不能在他人还握着指针时释放，回收策略与正确性绑定（<a href="/cs/lockfree-aba">无锁与 ABA</a>有总览）。正确性判据用线性化：每个并发操作等价于在它的调用与返回之间的某个瞬时原子生效的串行操作——没有这个判据，「对」与「快」都无从谈起。</p><p><span class="marginnote">ABA 的直觉版：你下楼前看见车位上停着一辆红色轿车，回来看到还停着红色轿车，就断定没人动过——其实别人开走又停回了一辆同款。CAS 只比对「现在像不像」，不比对「中间变过没有」，所以要版本号打标签或延迟回收来补上历史感。</span></p>',3)),(r(),o(i,null,{default:e(()=>[B(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E8%AF%BB%E5%BD%93%E5%89%8D%E5%80%BC%22%5D%20--%3E%20CAL%5B%22%E8%AE%A1%E7%AE%97%E6%96%B0%E5%80%BC%22%5D%0A%20%20CAL%20--%3E%20CAS%7B%22CAS%20%E6%8F%90%E4%BA%A4%E6%88%90%E5%8A%9F%3F%22%7D%0A%20%20CAS%20--%3E%7C%22%E6%98%AF%22%7C%20DONE%5B%22%E5%AF%B9%E8%B1%A1%E6%8E%A8%E8%BF%9B%E4%B8%80%E6%A0%BC%22%5D%0A%20%20CAS%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E5%80%BC%E5%B7%B2%E8%A2%AB%E5%88%AB%E4%BA%BA%E6%94%B9%22%7C%20REREAD%5B%22%E9%87%8D%E8%AF%BB%E9%87%8D%E8%AF%95%EF%BC%88%E8%AD%A6%E6%83%95%20ABA%EF%BC%89%22%5D%0A%20%20REREAD%20--%3E%20RD%0A%20%20PRE%5B%22%E6%9F%90%E4%B8%AA%E7%BA%BF%E7%A8%8B%E8%A2%AB%E6%8A%A2%E5%8D%A0%22%5D%20--%3E%20NOTE%5B%22%E5%85%B6%E4%BD%99%E7%BA%BF%E7%A8%8B%E7%85%A7%E5%B8%B8%E5%89%8D%E8%BF%9B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>进度谱系的结构由共识数给出：一个对象能无等待地解几路共识，决定它在 Herlihy 层次里的位置——读-写寄存器的共识数有限，CAS 与 LL/SC 是 \\(\\infty\\)，所以后者能「通用构造」任意对象，前者连无等待的先进先出队列都造不出。性能机制的另一面在缓存：一次 CAS 是对缓存行的读改写，x86 的 lock 前缀锁的是缓存行而非总线，争用的物理形态就是<a href="/cs/false-sharing">伪共享</a>式的行乒乓。安全发布靠 release 写配 acquire 读：发布者先把数据就位再翻标志，读者看到标志即看到数据，顺序由<a href="/cs/language-memory-model">语言内存模型</a>保证而不是运气。</p><p><span class="marginnote">共识数不是理论装饰：读-写寄存器的共识数是 \\(2\\)，因此不存在无等待的先进先出队列；CAS 的共识数是 \\(\\infty\\)，才有一切对象的通用构造——Herlihy, TOCS 1991。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写锁的排队机制（spinlock、mcs-lock 已给）；RCU 与 epoch 回收点名不展开；事务内存是另一条把组合性问题交给硬件的路（见<a href="/cs/transactional-memory">事务内存</a>），不在此并线。分布式共识与它词汇相同、模型不同：那里没有共享内存，只有消息，不在本课。也不要把无锁读成性能定理——它是进度规格；换性能要在屋顶图上重新记账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进度谱系：blocking → obstruction-free → lock-free → wait-free，代价逐级上升。</li><li>CAS 循环是主力；ABA 与内存回收是必须正面处理的两个坑。</li><li>正确性用线性化陈述；数据发布用 acquire/release，不靠运气。</li><li>无锁换来的是抗抢占的进度，不自动是性能；高争用下排队锁可能更稳。</li><li>出处：Herlihy, ACM TOCS 1991；Herlihy and Shavit, The Art of Multiprocessor Programming。</li></ul><p><span class="marginnote">术语翻译「线性化」：它不是要求代码真的一步不差地串行跑，而是要求每个并发操作的效果，等价于在「你调用」和「你拿到返回」之间的某个瞬间一步完成。有了这个判据，调用者可以放心把并发对象当串行对象推理——这是无锁结构敢叫「对」的依据。</span></p>',8))])}const S=t(c,[["render",p]]);export{_ as __pageData,S as default};
